import apiClient from './index';
import { ApiResponse, ChatMessageRequest, ChatMessageResponse } from './types';

export const chatApi = {
  // Отправка сообщения в AI
  sendMessage: async (
    request: ChatMessageRequest
  ): Promise<ApiResponse<ChatMessageResponse>> => {
      const response = await fetch('/api/chat', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ text: request.message })
      });

      const data = await response.json();
    return { data: { text: data.answer } as any, success: response.status === 200 };
  },

  // Получение истории чата
  getChatHistory: async (
    sessionId: string
  ): Promise<ApiResponse<ChatMessageResponse[]>> => {
    const response = await apiClient.get(`/chat/history/${sessionId}`);
    return response.data;
  },

  // Оценка ответа AI
  rateResponse: async (
    messageId: string,
    isPositive: boolean
  ): Promise<ApiResponse<void>> => {
    const response = await apiClient.post('/chat/rate', {
      messageId,
      isPositive,
    });
    return response.data;
  },

  // Получение быстрых вопросов (часто задаваемые)
  getQuickQuestions: async (): Promise<ApiResponse<string[]>> => {
    const response = await apiClient.get('/chat/quick-questions');
    return response.data;
  },

  // Создание новой сессии чата
  createSession: async (
    userId?: string
  ): Promise<ApiResponse<{ sessionId: string }>> => {
    const response = await apiClient.post('/chat/session', { userId });
    return response.data;
  },
};
