import React from 'react';
import { Box, IconButton, Tooltip, Typography } from '@mui/material';
import { ThumbUp, ThumbDown } from '@mui/icons-material';

interface RatingButtonsProps {
  messageId: string;
  onRate: (messageId: string, isPositive: boolean) => void;
  isMobile?: boolean;
}

const RatingButtons: React.FC<RatingButtonsProps> = ({ 
  messageId, 
  onRate, 
  isMobile = false 
}) => {
  return (
    <Box sx={{ 
      display: 'flex', 
      gap: isMobile ? 0.75 : 1, 
      mt: isMobile ? 0.75 : 1, 
      justifyContent: 'flex-start', 
      alignItems: 'center',
      flexWrap: isMobile ? 'wrap' : 'nowrap'
    }}>
      <Typography 
        variant="caption" 
        color="text.secondary" 
        sx={{ 
          mr: isMobile ? 0.5 : 1,
          fontSize: isMobile ? '0.7rem' : '0.75rem',
          whiteSpace: 'nowrap'
        }}
      >
        {isMobile ? 'Оценить:' : 'Оцените ответ:'}
      </Typography>
      
      <Tooltip title={isMobile ? "Полезно" : "Полезный ответ"}>
        <IconButton 
          size={isMobile ? "small" : "small"}
          color="success"
          onClick={() => onRate(messageId, true)}
          sx={{ 
            bgcolor: 'success.light',
            '&:hover': { 
              bgcolor: 'success.main',
              transform: 'scale(1.1)',
              transition: 'transform 0.2s'
            },
            width: isMobile ? 32 : 36,
            height: isMobile ? 32 : 36,
            p: isMobile ? 0.5 : 1
          }}
        >
          <ThumbUp fontSize={isMobile ? "small" : "small"} />
        </IconButton>
      </Tooltip>
      
      <Tooltip title={isMobile ? "Не полезно" : "Не полезный ответ"}>
        <IconButton 
          size={isMobile ? "small" : "small"}
          color="error"
          onClick={() => onRate(messageId, false)}
          sx={{ 
            bgcolor: 'error.light',
            '&:hover': { 
              bgcolor: 'error.main',
              transform: 'scale(1.1)',
              transition: 'transform 0.2s'
            },
            width: isMobile ? 32 : 36,
            height: isMobile ? 32 : 36,
            p: isMobile ? 0.5 : 1
          }}
        >
          <ThumbDown fontSize={isMobile ? "small" : "small"} />
        </IconButton>
      </Tooltip>

      {/* Альтернативный вариант для очень маленьких экранов */}
      {isMobile && (
        <Typography 
          variant="caption" 
          color="text.secondary"
          sx={{ 
            fontSize: '0.65rem',
            ml: 0.5,
            opacity: 0.7
          }}
        >
          (можно изменить)
        </Typography>
      )}
    </Box>
  );
};

export default RatingButtons;