import React from 'react';
import { Box, Button, Chip, Typography, useMediaQuery, useTheme } from '@mui/material';
import { CreditScore, Calculate, Timeline, Help, Savings, RateReview, SportsEsports } from '@mui/icons-material';

interface QuickButtonsProps {
  onQuestionClick: (question: string) => void;
  isMobile?: boolean;
  onCalculatorClick?: () => void;
  onGameClick?: () => void; // Пропс для игры
}

const QUICK_QUESTIONS = [
  { 
    text: "Как получить кредит?", 
    icon: <CreditScore fontSize="small" />,
    color: "primary" as const,
    shortText: "Получить кредит"
  },
  { 
    text: "Рассчитать платеж", 
    icon: <Calculate fontSize="small" />,
    color: "success" as const,
    shortText: "Расчёт"
  },
  { 
    text: "Рефинансирование", 
    icon: <Timeline fontSize="small" />,
    color: "info" as const,
    shortText: "Рефинансирование"
  },
  { 
    text: "Какие документы нужны?", 
    icon: <Help fontSize="small" />,
    color: "warning" as const,
    shortText: "Документы"
  },
  { 
    text: "Кредитная история", 
    icon: <Savings fontSize="small" />,
    color: "secondary" as const,
    shortText: "История"
  },
  { 
    text: "Процентные ставки", 
    icon: <RateReview fontSize="small" />,
    color: "error" as const,
    shortText: "Ставки"
  },
];

const QuickButtons: React.FC<QuickButtonsProps> = ({ 
  onQuestionClick, 
  isMobile = false,
  onCalculatorClick,
  onGameClick 
}) => {
  const theme = useTheme();
  const isVerySmall = useMediaQuery(theme.breakpoints.down(400));
  
  // Для мобильных показываем меньше вопросов
  const displayQuestions = isMobile 
    ? (isVerySmall ? QUICK_QUESTIONS.slice(0, 3) : QUICK_QUESTIONS.slice(0, 4))
    : QUICK_QUESTIONS;

  return (
    <Box sx={{ 
      display: 'flex', 
      flexDirection: 'column',
      gap: isMobile ? 1 : 1.5, 
      p: isMobile ? 1.5 : 2,
      mt: isMobile ? 1.5 : 2,
      borderTop: '1px solid',
      borderColor: 'divider',
      bgcolor: 'action.hover',
      borderRadius: isMobile ? 1.5 : 2,
      backdropFilter: 'blur(8px)',
      WebkitBackdropFilter: 'blur(8px)',
    }}>
      <Box sx={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center',
        flexWrap: 'wrap',
        gap: 0.5
      }}>
        <Chip 
          label={isMobile ? "Частые вопросы" : "Частые вопросы о кредитах"} 
          size="small" 
          color="primary" 
          variant="outlined"
          sx={{ 
            fontSize: isMobile ? '0.7rem' : '0.75rem',
            height: isMobile ? 24 : 28,
            fontWeight: 500,
          }}
        />
        
        {isMobile && !isVerySmall && (
          <Typography 
            variant="caption" 
            color="text.secondary"
            sx={{ fontSize: '0.65rem', opacity: 0.8 }}
          >
            {displayQuestions.length} из {QUICK_QUESTIONS.length}
          </Typography>
        )}
      </Box>
      
      {/* Упрощенный вариант без сложных условий */}
      <Box sx={{ 
        display: 'flex', 
        flexWrap: 'wrap', 
        gap: isMobile ? 0.75 : 1,
        justifyContent: isMobile ? 'center' : 'flex-start'
      }}>
        {displayQuestions.map((question, index) => (
          <Button
            key={index}
            variant="outlined"
            size={isMobile ? "small" : "small"}
            startIcon={isVerySmall ? undefined : question.icon}
            onClick={() => onQuestionClick(question.text)}
            color={question.color}
            sx={{
              borderRadius: isMobile ? 16 : 20,
              textTransform: 'none',
              borderWidth: isMobile ? 1 : 2,
              fontSize: isMobile ? (isVerySmall ? '0.7rem' : '0.75rem') : '0.875rem',
              padding: isMobile ? (isVerySmall ? '4px 8px' : '6px 12px') : '8px 16px',
              minHeight: isMobile ? 36 : 40,
              whiteSpace: 'normal',
              textAlign: 'center',
              lineHeight: 1.2,
              mt: 0.5,
              flexGrow: isMobile ? 1 : 0,
              minWidth: isMobile ? 'calc(50% - 8px)' : 'auto',
              '&:hover': {
                borderWidth: isMobile ? 1 : 2,
                transform: 'translateY(-1px)',
                transition: 'transform 0.2s'
              }
            }}
          >
            {isVerySmall ? question.shortText : (isMobile ? question.shortText : question.text)}
          </Button>
        ))}

        {/* Кнопка кредитного калькулятора */}
        {onCalculatorClick && (
          <Button
            variant="contained"
            size={isMobile ? "small" : "small"}
            startIcon={isVerySmall ? undefined : <Calculate fontSize="small" />}
            onClick={onCalculatorClick}
            color="success"
            sx={{
              borderRadius: isMobile ? 16 : 20,
              textTransform: 'none',
              fontSize: isMobile ? (isVerySmall ? '0.7rem' : '0.75rem') : '0.875rem',
              padding: isMobile ? (isVerySmall ? '4px 8px' : '6px 12px') : '8px 16px',
              minHeight: isMobile ? 36 : 40,
              whiteSpace: 'normal',
              textAlign: 'center',
              lineHeight: 1.2,
              mt: 0.5,
              flexGrow: isMobile ? 1 : 0,
              minWidth: isMobile ? '100%' : 'auto',
              backgroundColor: '#2E7D32',
              border: '2px solid',
              borderColor: 'success.main',
              '&:hover': {
                backgroundColor: '#1b5e20',
                transform: 'translateY(-1px)',
                boxShadow: 3,
                transition: 'all 0.2s'
              }
            }}
          >
            {isVerySmall ? 'Калькулятор' : (isMobile ? 'Кредитный калькулятор' : 'Кредитный калькулятор')}
          </Button>
        )}

        {/* Кнопка мини-игры */}
        {onGameClick && (
          <Button
            variant="contained"
            size={isMobile ? "small" : "small"}
            startIcon={isVerySmall ? undefined : <SportsEsports fontSize="small" />}
            onClick={onGameClick}
            color="secondary"
            sx={{
              borderRadius: isMobile ? 16 : 20,
              textTransform: 'none',
              fontSize: isMobile ? (isVerySmall ? '0.7rem' : '0.75rem') : '0.875rem',
              padding: isMobile ? (isVerySmall ? '4px 8px' : '6px 12px') : '8px 16px',
              minHeight: isMobile ? 36 : 40,
              whiteSpace: 'normal',
              textAlign: 'center',
              lineHeight: 1.2,
              mt: 0.5,
              flexGrow: isMobile ? 1 : 0,
              minWidth: isMobile ? '100%' : 'auto',
              backgroundColor: '#9c27b0',
              border: '2px solid',
              borderColor: 'secondary.main',
              '&:hover': {
                backgroundColor: '#7b1fa2',
                transform: 'translateY(-1px)',
                boxShadow: 3,
                transition: 'all 0.2s'
              }
            }}
          >
            {isVerySmall ? 'Игра' : (isMobile ? 'Обучающая игра' : 'Обучающая мини-игра')}
          </Button>
        )}
      </Box>

      {/* Информация о дополнительных инструментах */}
      {(onCalculatorClick || onGameClick) && (
        <Box sx={{ 
          p: 1, 
          mt: 1,
          borderRadius: 1,
          bgcolor: 'rgba(156, 39, 176, 0.05)',
          border: '1px solid',
          borderColor: 'rgba(156, 39, 176, 0.2)',
        }}>
          <Typography 
            variant="caption" 
            color="text.secondary"
            sx={{ 
              fontSize: '0.65rem', 
              textAlign: 'center',
              display: 'block'
            }}
          >
            🎓 <strong>Интерактивные инструменты:</strong> Используйте калькулятор и игру для лучшего понимания кредитов
          </Typography>
        </Box>
      )}

      {/* Показать кнопку "Показать еще" если вопросы скрыты на мобильных */}
      {isMobile && displayQuestions.length < QUICK_QUESTIONS.length && (
        <Box sx={{ textAlign: 'center', mt: 0.5 }}>
          <Typography 
            variant="caption" 
            color="text.secondary"
            sx={{ fontSize: '0.7rem', opacity: 0.7 }}
          >
            Остальные вопросы доступны на больших экранах
          </Typography>
        </Box>
      )}

      {/* Инструкция для пользователей на мобильных */}
      {isMobile && (
        <Typography 
          variant="caption" 
          color="text.secondary"
          sx={{ 
            fontSize: '0.65rem', 
            textAlign: 'center',
            opacity: 0.6,
            mt: 0.5
          }}
        >
          Нажмите на вопрос для быстрого ответа
        </Typography>
      )}
    </Box>
  );
};

export default QuickButtons;