import React, { useState, useRef, useContext } from 'react';
import { Box, TextField, IconButton, Tooltip, Badge, Typography, Chip } from '@mui/material';
import { Send, AttachFile, InsertDriveFile, PictureAsPdf, Image, Description, Close } from '@mui/icons-material';
import { ThemeContext } from '../../App';

interface InputAreaProps {
  onSendMessage: (message: string, files?: File[]) => void;
  onAttachFile?: (file: File) => void;
  disabled?: boolean; // Добавлен пропс disabled
}

const InputArea: React.FC<InputAreaProps> = ({ 
  onSendMessage, 
  onAttachFile,
  disabled = false // Значение по умолчанию
}) => {
  const [input, setInput] = useState('');
  const [attachedFiles, setAttachedFiles] = useState<File[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { isDarkMode } = useContext(ThemeContext);

  const handleSend = () => {
    if ((input.trim() || attachedFiles.length > 0) && !disabled) {
      onSendMessage(input, attachedFiles);
      setInput('');
      setAttachedFiles([]);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey && !disabled) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleAttachClick = () => {
    if (!disabled) {
      fileInputRef.current?.click();
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (disabled) return;
    
    const files = e.target.files;
    if (files && files.length > 0) {
      const fileList = Array.from(files);
      setAttachedFiles(prev => [...prev, ...fileList]);
      
      if (onAttachFile) {
        fileList.forEach(file => onAttachFile(file));
      }
      
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    }
  };

  const removeFile = (index: number) => {
    if (!disabled) {
      setAttachedFiles(prev => prev.filter((_, i) => i !== index));
    }
  };

  const getFileIcon = (type: string) => {
    if (type.includes('pdf')) return <PictureAsPdf fontSize="small" />;
    if (type.includes('image')) return <Image fontSize="small" />;
    if (type.includes('text') || type.includes('doc')) return <Description fontSize="small" />;
    return <InsertDriveFile fontSize="small" />;
  };

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  return (
    <Box sx={{ 
      p: 2, 
      borderTop: '1px solid', 
      borderColor: 'divider',
      bgcolor: isDarkMode ? 'background.paper' : 'white',
      opacity: disabled ? 0.6 : 1, // Добавляем визуальный индикатор отключения
      transition: 'opacity 0.2s ease'
    }}>
      {/* Показать прикрепленные файлы */}
      {attachedFiles.length > 0 && (
        <Box sx={{ 
          mb: 2, 
          p: 1.5, 
          borderRadius: 2,
          bgcolor: isDarkMode ? 'rgba(255, 255, 255, 0.05)' : 'rgba(0, 0, 0, 0.02)',
          border: `1px dashed ${isDarkMode ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.1)'}`,
          opacity: disabled ? 0.7 : 1
        }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
            <Typography variant="caption" color="text.secondary">
              Прикрепленные файлы ({attachedFiles.length})
            </Typography>
            <Chip 
              label="Очистить все" 
              size="small" 
              onClick={() => !disabled && setAttachedFiles([])}
              variant="outlined"
              sx={{ 
                fontSize: '0.7rem',
                cursor: disabled ? 'not-allowed' : 'pointer',
                opacity: disabled ? 0.5 : 1
              }}
              disabled={disabled}
            />
          </Box>
          
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
            {attachedFiles.map((file, index) => (
              <Box
                key={index}
                sx={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 1.5,
                  p: 1.5,
                  borderRadius: 1.5,
                  bgcolor: isDarkMode ? 'rgba(255, 255, 255, 0.08)' : 'rgba(0, 0, 0, 0.03)',
                  border: `1px solid ${isDarkMode ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.08)'}`,
                  '&:hover': {
                    bgcolor: disabled ? undefined : (isDarkMode ? 'rgba(255, 255, 255, 0.12)' : 'rgba(0, 0, 0, 0.05)')
                  },
                  opacity: disabled ? 0.7 : 1
                }}
              >
                <Box sx={{ 
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  width: 36,
                  height: 36,
                  borderRadius: 1,
                  bgcolor: isDarkMode ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.06)',
                  color: 'primary.main'
                }}>
                  {getFileIcon(file.type)}
                </Box>

                <Box sx={{ flexGrow: 1, minWidth: 0 }}>
                  <Typography 
                    variant="body2" 
                    sx={{ 
                      fontWeight: 500,
                      whiteSpace: 'nowrap',
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      color: isDarkMode ? 'text.primary' : 'text.primary'
                    }}
                  >
                    {file.name}
                  </Typography>
                  <Typography 
                    variant="caption" 
                    color="text.secondary"
                    sx={{ display: 'block' }}
                  >
                    {formatFileSize(file.size)}
                  </Typography>
                </Box>

                <IconButton
                  size="small"
                  onClick={() => !disabled && removeFile(index)}
                  sx={{ 
                    color: isDarkMode ? '#f44336' : '#d32f2f',
                    '&:hover': { 
                      bgcolor: disabled ? undefined : (isDarkMode ? 'rgba(244, 67, 54, 0.1)' : 'rgba(211, 47, 47, 0.1)')
                    },
                    cursor: disabled ? 'not-allowed' : 'pointer',
                    opacity: disabled ? 0.5 : 1
                  }}
                  disabled={disabled}
                >
                  <Close fontSize="small" />
                </IconButton>
              </Box>
            ))}
          </Box>
        </Box>
      )}

      {/* Поле ввода и кнопки */}
      <Box sx={{ display: 'flex', gap: 1, alignItems: 'flex-end' }}>
        <input
          type="file"
          ref={fileInputRef}
          onChange={handleFileChange}
          style={{ display: 'none' }}
          multiple
          accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.jpeg,.png,.txt,.zip"
          disabled={disabled}
        />
        
        <Tooltip title={disabled ? "Отправка сообщений временно недоступна" : "Прикрепить файл (PDF, документы, изображения)"}>
          <Badge 
            badgeContent={attachedFiles.length} 
            color="primary"
            overlap="circular"
            sx={{ 
              '& .MuiBadge-badge': {
                fontSize: '0.7rem',
                height: 18,
                minWidth: 18,
                opacity: disabled ? 0.5 : 1
              }
            }}
          >
            <IconButton 
              onClick={handleAttachClick}
              color="primary"
              disabled={disabled}
              sx={{
                bgcolor: disabled 
                  ? (isDarkMode ? 'rgba(255, 255, 255, 0.05)' : 'rgba(0, 0, 0, 0.02)') 
                  : (isDarkMode ? 'rgba(255, 255, 255, 0.1)' : 'rgba(0, 0, 0, 0.04)'),
                '&:hover': {
                  bgcolor: disabled 
                    ? undefined 
                    : (isDarkMode ? 'rgba(255, 255, 255, 0.2)' : 'rgba(0, 0, 0, 0.08)'),
                  transform: disabled ? undefined : 'scale(1.05)',
                  transition: 'transform 0.2s'
                },
                cursor: disabled ? 'not-allowed' : 'pointer',
                opacity: disabled ? 0.5 : 1
              }}
            >
              <AttachFile />
            </IconButton>
          </Badge>
        </Tooltip>

        <TextField
          fullWidth
          multiline
          maxRows={4}
          value={input}
          onChange={(e) => !disabled && setInput(e.target.value)}
          onKeyPress={handleKeyPress}
          placeholder={disabled ? "Отправка сообщений временно недоступна..." : 
                   attachedFiles.length > 0 ? "Добавьте комментарий к файлам..." : "Введите сообщение..."}
          variant="outlined"
          size="small"
          disabled={disabled}
          sx={{
            '& .MuiOutlinedInput-root': {
              borderRadius: 2,
              bgcolor: isDarkMode ? 'rgba(255, 255, 255, 0.05)' : 'white',
              '&.Mui-disabled': {
                bgcolor: isDarkMode ? 'rgba(255, 255, 255, 0.03)' : 'rgba(0, 0, 0, 0.02)',
                cursor: 'not-allowed'
              }
            },
            '& .MuiInputBase-input.Mui-disabled': {
              WebkitTextFillColor: isDarkMode ? 'rgba(255, 255, 255, 0.5)' : 'rgba(0, 0, 0, 0.5)',
              cursor: 'not-allowed'
            }
          }}
        />

        <Tooltip title={disabled ? "Ожидание ответа от сервера..." : "Отправить сообщение"}>
          <IconButton 
            onClick={handleSend} 
            color="primary"
            disabled={disabled || (!input.trim() && attachedFiles.length === 0)}
            sx={{
              height: 40,
              width: 40,
              bgcolor: disabled 
                ? 'action.disabled' 
                : (input.trim() || attachedFiles.length > 0) ? 'primary.main' : 'action.disabled',
              color: disabled 
                ? 'action.disabledBackground' 
                : (input.trim() || attachedFiles.length > 0) ? 'primary.contrastText' : 'action.disabledBackground',
              '&:hover': {
                bgcolor: disabled 
                  ? 'action.disabled' 
                  : (input.trim() || attachedFiles.length > 0) ? 'primary.dark' : 'action.disabled',
                transform: disabled ? undefined : 'scale(1.05)',
                transition: 'transform 0.2s'
              },
              '&.Mui-disabled': {
                bgcolor: isDarkMode ? 'rgba(255, 255, 255, 0.12)' : 'rgba(0, 0, 0, 0.12)',
                cursor: 'not-allowed'
              },
              opacity: disabled ? 0.7 : 1
            }}
          >
            <Send />
          </IconButton>
        </Tooltip>
      </Box>

      <Box sx={{ mt: 1, display: 'flex', justifyContent: 'space-between' }}>
        <Typography variant="caption" color="text.secondary">
          Поддерживаемые форматы: PDF, DOC, XLS, JPG, PNG
        </Typography>
        <Typography variant="caption" color="text.secondary">
          Макс. размер: 10MB
        </Typography>
      </Box>
    </Box>
  );
};

export default InputArea;