import React, { useContext } from 'react';
import { 
  IconButton, 
  Tooltip, 
  Badge,
  Box 
} from '@mui/material';
import { SportsEsports, EmojiEvents, TrendingDown } from '@mui/icons-material';
import { ThemeContext } from '../../App';

interface GameButtonProps {
  onClick: () => void;
  isMobile?: boolean;
}

const GameButton: React.FC<GameButtonProps> = ({ onClick, isMobile = false }) => {
  const { isDarkMode } = useContext(ThemeContext);

  return (
    <Tooltip title="Мини-игра: Погаси кредит быстрее!" arrow placement="top">
      <Box sx={{ position: 'relative' }}>
        <IconButton
          onClick={onClick}
          sx={{
            bgcolor: isDarkMode 
              ? 'rgba(156, 39, 176, 0.2)' 
              : 'rgba(156, 39, 176, 0.1)',
            color: isDarkMode ? '#ab47bc' : '#7b1fa2',
            border: `1px solid ${isDarkMode ? 'rgba(171, 71, 188, 0.3)' : 'rgba(123, 31, 162, 0.2)'}`,
            borderRadius: 2,
            p: isMobile ? 1.2 : 1.5,
            '&:hover': {
              bgcolor: isDarkMode 
                ? 'rgba(171, 71, 188, 0.3)' 
                : 'rgba(156, 39, 176, 0.15)',
              transform: 'translateY(-2px)',
              boxShadow: 2,
            },
            transition: 'all 0.3s ease',
          }}
        >
          <SportsEsports fontSize={isMobile ? "medium" : "large"} />
          {/* Маленькая иконка трофея */}
          <Box
            sx={{
              position: 'absolute',
              top: 4,
              right: 4,
              bgcolor: isDarkMode ? '#ff9800' : '#f57c00',
              borderRadius: '50%',
              width: 16,
              height: 16,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}
          >
            <EmojiEvents sx={{ fontSize: 10, color: 'white' }} />
          </Box>
        </IconButton>
        {/* Бейдж для привлечения внимания */}
        <Badge
          color="secondary"
          badgeContent="🎮"
          sx={{
            position: 'absolute',
            top: -8,
            right: -8,
            '& .MuiBadge-badge': {
              fontSize: isMobile ? '0.6rem' : '0.7rem',
              padding: '0 4px',
              borderRadius: 1,
              backgroundColor: 'transparent',
              color: '#ff4081',
            }
          }}
        />
      </Box>
    </Tooltip>
  );
};

export default GameButton;