import React, { useState, useMemo, createContext, useContext } from 'react';
import { ThemeProvider, createTheme, CssBaseline, Box } from '@mui/material';
import ChatWindow from './components/ChatWindow/ChatWindow';

// Импорт фоновой картинки
import chatBackground from './assets/3164116.jpg';

// Контекст для переключения темы
export const ThemeContext = createContext({
  toggleTheme: () => {},
  isDarkMode: false,
});

function App() {
  const [isDarkMode, setIsDarkMode] = useState(false);

  const theme = useMemo(() => 
    createTheme({
      palette: {
        mode: isDarkMode ? 'dark' : 'light',
        primary: {
          main: isDarkMode ? '#4CAF50' : '#2E7032', // Зелёный Сбера
        },
        background: {
          default: isDarkMode ? '#121212' : '#f8fdf9',
          paper: isDarkMode ? '#1E1E1E' : '#ffffff',
        },
      },
      typography: {
        fontFamily: '"Segoe UI", Roboto, Helvetica, Arial, sans-serif',
      },
      shape: {
        borderRadius: 12,
      },
      // Кастомные стили для компонентов
      components: {
        MuiPaper: {
          styleOverrides: {
            root: {
              backgroundImage: 'none',
            }
          }
        }
      }
    }), [isDarkMode]
  );

  const toggleTheme = () => {
    setIsDarkMode(!isDarkMode);
  };

  return (
    <ThemeContext.Provider value={{ toggleTheme, isDarkMode }}>
      <ThemeProvider theme={theme}>
        <CssBaseline />
        {/* Основной контейнер с фоновой картинкой */}
        <Box
          sx={{
            minHeight: '100vh',
            width: '100%',
            // Фоновая картинка
            backgroundImage: `url(${chatBackground})`,
            backgroundSize: 'cover',          // растягиваем на весь экран
            backgroundPosition: 'center',     // центрируем
            backgroundRepeat: 'no-repeat',    // не повторяем
            backgroundAttachment: 'fixed',    // фиксируем фон при скролле
            // Фолбэк цвет на случай если картинка не загрузится
            backgroundColor: isDarkMode ? '#121212' : '#f8fdf9',
            // Позиционирование для overlay
            position: 'relative',
          }}
        >
          {/* Overlay для улучшения читаемости */}
          <Box
            sx={{
              position: 'absolute',
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              backgroundColor: isDarkMode 
                ? 'rgba(0, 0, 0, 0.6)'      // темный оверлей для темной темы
                : 'rgba(255, 255, 255, 0.7)', // светлый оверлей для светлой
              zIndex: 0,
            }}
          />
          
          {/* Контент поверх фона */}
          <Box
            sx={{
              position: 'relative',
              zIndex: 1,
              minHeight: '100vh',
              display: 'flex',
              flexDirection: 'column',
            }}
          >
            <ChatWindow />
          </Box>
        </Box>
      </ThemeProvider>
    </ThemeContext.Provider>
  );
}

export default App;