import React, { useState, useEffect, useContext } from 'react';
import { gameApi } from '../../api/game.api';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Box,
  Typography,
  Button,
  Paper,
  LinearProgress,
  Chip,
  IconButton,
  Grid,
  Card,
  CardContent,
  Slider,
  Alert,
  Fade,
  Zoom,
  useMediaQuery,
  useTheme,
  TextField,
  InputAdornment
} from '@mui/material';
import {
  Close,
  SportsEsports,
  EmojiEvents,
  TrendingDown,
  Savings,
  Timeline,
  AttachMoney,
  RestartAlt,
  Share,
  Info,
  CheckCircle,
  Warning
} from '@mui/icons-material';
import { ThemeContext } from '../../App';

interface GameProps {
  open: boolean;
  onClose: () => void;
}

interface GameStats {
  totalMonths: number;
  totalInterest: number;
  moneySaved: number;
  bestTime: number;
}

const CreditGame: React.FC<GameProps> = ({ open, onClose }) => {
  const { isDarkMode } = useContext(ThemeContext);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  
  // Игровые состояния
  const [debt, setDebt] = useState<number>(300000);
  const [month, setMonth] = useState<number>(0);
  const [isCompleted, setIsCompleted] = useState<boolean>(false);
  const [gameActive, setGameActive] = useState<boolean>(true);
  const [extraPayment, setExtraPayment] = useState<number>(5000);
  const [paymentHistory, setPaymentHistory] = useState<Array<{month: number, payment: number, interest: number}>>([]);
  const [stats, setStats] = useState<GameStats>({
    totalMonths: 0,
    totalInterest: 0,
    moneySaved: 0,
    bestTime: 24 // начальный "рекорд" - стандартный срок
  });

  const interestRate = 0.15 / 12; // 15% годовых → месячная ставка
  const standardTerm = 24; // стандартный срок кредита

  // Рассчет минимального платежа
  const calculateMinPayment = (currentDebt: number): number => {
    if (currentDebt <= 0) return 0;
    const remainingMonths = Math.max(1, standardTerm - month);
    const monthlyRate = interestRate;
    return Math.round((currentDebt * monthlyRate) / (1 - Math.pow(1 + monthlyRate, -remainingMonths)));
  };

  // Обработка платежа
  const handlePayment = (extra: number) => {
    if (!gameActive || debt <= 0) return;

    const minPayment = calculateMinPayment(debt);
    const totalPayment = minPayment + extra;
    const interest = Math.round(debt * interestRate);
    const principal = Math.round(totalPayment - interest);

    // Добавляем в историю
    setPaymentHistory(prev => [...prev, {
      month: month + 1,
      payment: totalPayment,
      interest: interest
    }]);

    if (totalPayment >= debt) {
      // Кредит погашен!
      const finalMonth = month + 1;
      const savedMonths = standardTerm - finalMonth;
      const moneySaved = Math.round(savedMonths * minPayment * 0.7); // Примерная экономия
      
      setDebt(0);
      setMonth(finalMonth);
      setIsCompleted(true);
      setGameActive(false);
      
      // Обновляем статистику
      setStats(prev => ({
        ...prev,
        totalMonths: finalMonth,
        totalInterest: prev.totalInterest + interest,
        moneySaved: moneySaved,
        bestTime: finalMonth < prev.bestTime ? finalMonth : prev.bestTime
      }));
    } else {
      const newDebt = debt - principal;
      setDebt(newDebt);
      setMonth(prev => prev + 1);
      
      // Обновляем статистику
      setStats(prev => ({
        ...prev,
        totalInterest: prev.totalInterest + interest
      }));
    }
  };

  // Сброс игры
  const resetGame = () => {
    setDebt(300000);
    setMonth(0);
    setIsCompleted(false);
    setGameActive(true);
    setPaymentHistory([]);
    setStats(prev => ({
      ...prev,
      totalInterest: 0
    }));
  };

  // Рассчет прогресса
  const progress = Math.max(0, Math.min(100, ((300000 - debt) / 300000) * 100));

  // Рассчет экономии
  const calculateSavings = () => {
    if (isCompleted) {
      const savedMonths = standardTerm - month;
      return Math.round(savedMonths * calculateMinPayment(300000) * 0.7);
    }
    return 0;
  };

  // Эффект для анимации
  useEffect(() => {
    if (isCompleted) {
      const timer = setTimeout(() => {
        // Можно добавить дополнительные анимации
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [isCompleted]);

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="md"
      fullWidth
      fullScreen={isMobile}
      PaperProps={{
        sx: {
          borderRadius: isMobile ? 0 : 2,
          bgcolor: isDarkMode ? '#1a1a1a' : '#ffffff',
          backgroundImage: 'none',
          maxHeight: isMobile ? '100vh' : '90vh',
          overflow: 'hidden',
        }
      }}
    >
      <DialogTitle sx={{ 
        bgcolor: isDarkMode ? 'rgba(156, 39, 176, 0.1)' : 'rgba(156, 39, 176, 0.05)',
        borderBottom: `1px solid ${isDarkMode ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)'}`,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        backdropFilter: 'blur(10px)',
      }}>
        <Box display="flex" alignItems="center" gap={2}>
          <SportsEsports color="secondary" />
          <Typography variant="h6" fontWeight={600}>
            Мини-игра: Погаси кредит быстрее!
          </Typography>
          <Chip 
            label="Обучение" 
            size="small" 
            color="secondary" 
            variant="outlined"
            icon={<TrendingDown fontSize="small" />}
          />
        </Box>
        <IconButton onClick={onClose} size="small">
          <Close />
        </IconButton>
      </DialogTitle>

      <DialogContent sx={{ p: 0 }}>
        <Box p={isMobile ? 2 : 3}>
          {/* Статус игры */}
          <Paper 
            elevation={0}
            sx={{ 
              p: 2, 
              mb: 3,
              borderRadius: 2,
              bgcolor: isDarkMode ? 'rgba(156, 39, 176, 0.1)' : 'rgba(156, 39, 176, 0.05)',
              border: `1px solid ${isDarkMode ? 'rgba(171, 71, 188, 0.3)' : 'rgba(156, 39, 176, 0.2)'}`,
            }}
          >
            <Grid container spacing={2}>
              <Grid item xs={12} sm={6}>
                <Typography variant="body2" color="text.secondary" gutterBottom>
                  Остаток долга
                </Typography>
                <Typography variant="h4" fontWeight={700} color={debt > 0 ? 'text.primary' : 'success.main'}>
                  {debt.toLocaleString('ru-RU')} ₽
                </Typography>
              </Grid>
              <Grid item xs={12} sm={6}>
                <Typography variant="body2" color="text.secondary" gutterBottom>
                  Прошло месяцев
                </Typography>
                <Typography variant="h4" fontWeight={700} color="primary">
                  {month}
                </Typography>
              </Grid>
            </Grid>
          </Paper>

          {/* Прогресс бар */}
          <Box mb={3}>
            <Box display="flex" justifyContent="space-between" mb={1}>
              <Typography variant="body2" color="text.secondary">
                Прогресс погашения
              </Typography>
              <Typography variant="body2" fontWeight={600} color="primary">
                {progress.toFixed(1)}%
              </Typography>
            </Box>
            <LinearProgress 
              variant="determinate" 
              value={progress} 
              sx={{ 
                height: 12, 
                borderRadius: 6,
                bgcolor: isDarkMode ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)',
                '& .MuiLinearProgress-bar': {
                  background: 'linear-gradient(90deg, #4caf50, #8bc34a)',
                  borderRadius: 6,
                }
              }}
            />
            <Box display="flex" justifyContent="space-between" mt={1}>
              <Typography variant="caption" color="text.secondary">
                Начало: 300,000 ₽
              </Typography>
              <Typography variant="caption" color="text.secondary">
                Цель: 0 ₽
              </Typography>
            </Box>
          </Box>

          {/* Статистика */}
          <Grid container spacing={2} mb={3}>
            <Grid item xs={6} sm={3}>
              <Card 
                elevation={0}
                sx={{ 
                  bgcolor: isDarkMode ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.02)',
                  border: `1px solid ${isDarkMode ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)'}`,
                }}
              >
                <CardContent sx={{ p: 2, textAlign: 'center' }}>
                  <AttachMoney fontSize="small" color="primary" />
                  <Typography variant="h6" fontWeight={700}>
                    {calculateMinPayment(debt).toLocaleString('ru-RU')} ₽
                  </Typography>
                  <Typography variant="caption" color="text.secondary">
                    Мин. платёж
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={6} sm={3}>
              <Card 
                elevation={0}
                sx={{ 
                  bgcolor: isDarkMode ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.02)',
                  border: `1px solid ${isDarkMode ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)'}`,
                }}
              >
                <CardContent sx={{ p: 2, textAlign: 'center' }}>
                  <Timeline fontSize="small" color="secondary" />
                  <Typography variant="h6" fontWeight={700}>
                    {stats.totalInterest.toLocaleString('ru-RU')} ₽
                  </Typography>
                  <Typography variant="caption" color="text.secondary">
                    Всего процентов
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={6} sm={3}>
              <Card 
                elevation={0}
                sx={{ 
                  bgcolor: isDarkMode ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.02)',
                  border: `1px solid ${isDarkMode ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)'}`,
                }}
              >
                <CardContent sx={{ p: 2, textAlign: 'center' }}>
                  <Savings fontSize="small" color="success" />
                  <Typography variant="h6" fontWeight={700}>
                    {calculateSavings().toLocaleString('ru-RU')} ₽
                  </Typography>
                  <Typography variant="caption" color="text.secondary">
                    Экономия
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
            <Grid item xs={6} sm={3}>
              <Card 
                elevation={0}
                sx={{ 
                  bgcolor: isDarkMode ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.02)',
                  border: `1px solid ${isDarkMode ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)'}`,
                }}
              >
                <CardContent sx={{ p: 2, textAlign: 'center' }}>
                  <EmojiEvents fontSize="small" color="warning" />
                  <Typography variant="h6" fontWeight={700}>
                    {stats.bestTime}
                  </Typography>
                  <Typography variant="caption" color="text.secondary">
                    Рекорд (мес.)
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          </Grid>

          {/* Блок с кнопками платежей - ВАРИАНТ 2 */}
          {!isCompleted && gameActive ? (
            <Zoom in={true}>
              <Paper 
                elevation={0}
                sx={{ 
                  p: 3, 
                  mb: 3,
                  borderRadius: 2,
                  bgcolor: isDarkMode ? 'rgba(76, 175, 80, 0.1)' : 'rgba(76, 175, 80, 0.05)',
                  border: `1px solid ${isDarkMode ? 'rgba(76, 175, 80, 0.3)' : 'rgba(76, 175, 80, 0.2)'}`,
                }}
              >
                <Typography variant="h6" gutterBottom textAlign="center" color="primary">
                  Введите сумму для досрочного погашения
                </Typography>

                <Box display="flex" flexDirection={isMobile ? "column" : "row"} gap={2} alignItems="center" justifyContent="center">
                  {/* Поле для ввода суммы */}
                  <TextField
                    label="Сумма доплаты"
                    type="number"
                    variant="outlined"
                    value={extraPayment}
                    onChange={(e) => {
                      let value = parseInt(e.target.value) || 0;
                      // Ограничиваем введенную сумму
                      const maxAllowed = Math.min(50000, debt);
                      value = Math.max(0, Math.min(value, maxAllowed));
                      setExtraPayment(value);
                    }}
                    InputProps={{
                      endAdornment: <InputAdornment position="end">₽</InputAdornment>,
                      inputProps: { 
                        min: 0, 
                        max: Math.min(50000, debt),
                        step: 1000 
                      }
                    }}
                    helperText={`Максимум: ${Math.min(50000, debt).toLocaleString('ru-RU')} ₽`}
                    sx={{ flexGrow: 1, maxWidth: 300 }}
                  />

                  {/* Кнопки действий */}
                  <Button
                    variant="contained"
                    size="large"
                    color="success"
                    startIcon={<TrendingDown />}
                    onClick={() => handlePayment(extraPayment)}
                    disabled={extraPayment === 0}
                    sx={{ minWidth: 200 }}
                  >
                    Внести {extraPayment.toLocaleString('ru-RU')} ₽
                  </Button>
                </Box>

                <Box display="flex" gap={2} justifyContent="center" mt={3} flexWrap="wrap">
                  <Button
                    variant="outlined"
                    size="medium"
                    startIcon={<AttachMoney />}
                    onClick={() => handlePayment(0)}
                  >
                    Только минимальный платёж
                  </Button>
                  
                  <Button
                    variant="outlined"
                    size="medium"
                    color="secondary"
                    startIcon={<Savings />}
                    onClick={() => {
                      // Устанавливаем доплату равной оставшемуся долгу
                      const remainingDebt = debt;
                      setExtraPayment(remainingDebt);
                      handlePayment(remainingDebt);
                    }}
                  >
                    Погасить весь долг
                  </Button>
                </Box>
              </Paper>
            </Zoom>
          ) : null}

          {/* Поздравление при победе */}
          {isCompleted && (
            <Fade in={true}>
              <Paper 
                elevation={0}
                sx={{ 
                  p: 3, 
                  mb: 3,
                  borderRadius: 2,
                  bgcolor: isDarkMode ? 'rgba(255, 193, 7, 0.1)' : 'rgba(255, 193, 7, 0.05)',
                  border: `1px solid ${isDarkMode ? 'rgba(255, 193, 7, 0.3)' : 'rgba(255, 193, 7, 0.2)'}`,
                  textAlign: 'center',
                }}
              >
                <EmojiEvents sx={{ fontSize: 60, color: '#ff9800', mb: 2 }} />
                <Typography variant="h5" fontWeight={700} color="success.main" gutterBottom>
                  🎉 Поздравляем!
                </Typography>
                <Typography variant="h6" gutterBottom>
                  Вы погасили кредит за {month} месяцев!
                </Typography>
                <Typography variant="body1" color="text.secondary" paragraph>
                  Вы сэкономили <strong>{calculateSavings().toLocaleString('ru-RU')} ₽</strong>, 
                  погасив кредит на {standardTerm - month} месяцев раньше срока!
                </Typography>
                
                <Alert 
                  severity="success" 
                  icon={<CheckCircle />}
                  sx={{ mb: 2 }}
                >
                  Отличный результат! Вы продемонстрировали отличные навыки финансового планирования.
                </Alert>
              </Paper>
            </Fade>
          )}

          {/* История платежей */}
          {paymentHistory.length > 0 && (
            <Paper 
              elevation={0}
              sx={{ 
                p: 2, 
                borderRadius: 2,
                bgcolor: isDarkMode ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.02)',
                border: `1px solid ${isDarkMode ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)'}`,
              }}
            >
              <Typography variant="subtitle1" fontWeight={600} gutterBottom>
                История платежей
              </Typography>
              <Box sx={{ maxHeight: 200, overflow: 'auto' }}>
                {paymentHistory.map((item, index) => (
                  <Box key={index} display="flex" justifyContent="space-between" py={1} borderBottom="1px solid" borderColor="divider">
                    <Typography variant="body2">Месяц {item.month}</Typography>
                    <Typography variant="body2" fontWeight={600}>{item.payment.toLocaleString('ru-RU')} ₽</Typography>
                    <Typography variant="body2" color="text.secondary">(проценты: {item.interest.toLocaleString('ru-RU')} ₽)</Typography>
                  </Box>
                ))}
              </Box>
            </Paper>
          )}

          {/* Подсказки */}
          <Alert 
            severity="info" 
            icon={<Info />}
            sx={{ mt: 3 }}
          >
            <Typography variant="body2">
              <strong>Совет:</strong> Чем больше вы платите сверх минимального платежа, тем быстрее погасите кредит и сэкономите на процентах!
            </Typography>
          </Alert>
        </Box>
      </DialogContent>

      <DialogActions sx={{ 
        p: 2,
        borderTop: `1px solid ${isDarkMode ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)'}`,
        bgcolor: isDarkMode ? 'rgba(45, 45, 45, 0.5)' : 'rgba(248, 253, 249, 0.5)',
        backdropFilter: 'blur(10px)',
      }}>
        <Button 
          startIcon={<RestartAlt />}
          onClick={resetGame}
          variant="outlined"
        >
          Начать заново
        </Button>
        <Box flex={1} />
        <Button onClick={onClose} color="inherit">
          Закрыть
        </Button>
        {isCompleted && (
          <Button 
            variant="contained" 
            startIcon={<Share />}
            onClick={() => {
              // Можно добавить функцию "Поделиться результатом"
              alert(`Я погасил кредит за ${month} месяцев в мини-игре от Сбербанка! Попробуй и ты!`);
            }}
            color="secondary"
          >
            Поделиться результатом
          </Button>
        )}
      </DialogActions>
    </Dialog>
  );
};

export default CreditGame;