import React, { useState, useContext, useEffect } from 'react';
import { calculatorApi } from '../../api/calculator.api';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Box,
  TextField,
  Slider,
  Typography,
  Button,
  Grid,
  Paper,
  Divider,
  IconButton,
  Alert,
  Tabs,
  Tab,
  Switch,
  FormControlLabel,
  Chip,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  useMediaQuery,
  useTheme
} from '@mui/material';
import {
  Close,
  Calculate,
  TrendingUp,
  Savings,
  Timeline,
  ShowChart,
  AttachMoney,
  Schedule,
  Percent,
  Info
} from '@mui/icons-material';
import { ThemeContext } from '../../App';

interface CalculatorProps {
  open: boolean;
  onClose: () => void;
}

interface PaymentSchedule {
  month: number;
  payment: number;
  principal: number;
  interest: number;
  balance: number;
}

const CreditCalculator: React.FC<CalculatorProps> = ({ open, onClose }) => {
  const { isDarkMode } = useContext(ThemeContext);
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  
  const [loanAmount, setLoanAmount] = useState<number>(500000);
  const [loanTerm, setLoanTerm] = useState<number>(12);
  const [interestRate, setInterestRate] = useState<number>(12.9);
  const [paymentType, setPaymentType] = useState<'annuity' | 'differentiated'>('annuity');
  const [activeTab, setActiveTab] = useState<number>(0);
  const [showSchedule, setShowSchedule] = useState<boolean>(false);
  const [schedule, setSchedule] = useState<PaymentSchedule[]>([]);

  // Рассчет платежа
  const calculatePayment = () => {
    const monthlyRate = interestRate / 100 / 12;
    
    if (paymentType === 'annuity') {
      // Аннуитетный платеж
      const annuityCoefficient = (monthlyRate * Math.pow(1 + monthlyRate, loanTerm)) / 
                                (Math.pow(1 + monthlyRate, loanTerm) - 1);
      return Math.round(loanAmount * annuityCoefficient);
    } else {
      // Дифференцированный платеж (первый месяц)
      const principalPayment = loanAmount / loanTerm;
      const interestPayment = loanAmount * monthlyRate;
      return Math.round(principalPayment + interestPayment);
    }
  };

  const calculateTotalPayment = () => {
    return calculatePayment() * loanTerm;
  };

  const calculateOverpayment = () => {
    return calculateTotalPayment() - loanAmount;
  };

  // Рассчит графика платежей
  const calculatePaymentSchedule = () => {
    const monthlyRate = interestRate / 100 / 12;
    let balance = loanAmount;
    const scheduleData: PaymentSchedule[] = [];
    
    if (paymentType === 'annuity') {
      const monthlyPayment = calculatePayment();
      
      for (let month = 1; month <= loanTerm; month++) {
        const interest = balance * monthlyRate;
        const principal = monthlyPayment - interest;
        balance -= principal;
        
        scheduleData.push({
          month,
          payment: Math.round(monthlyPayment),
          principal: Math.round(principal),
          interest: Math.round(interest),
          balance: Math.max(0, Math.round(balance))
        });
      }
    } else {
      const principalPayment = loanAmount / loanTerm;
      
      for (let month = 1; month <= loanTerm; month++) {
        const interest = balance * monthlyRate;
        const payment = principalPayment + interest;
        balance -= principalPayment;
        
        scheduleData.push({
          month,
          payment: Math.round(payment),
          principal: Math.round(principalPayment),
          interest: Math.round(interest),
          balance: Math.max(0, Math.round(balance))
        });
      }
    }
    
    setSchedule(scheduleData);
  };

  // Рассчит выгоды рефинансирования
  const calculateRefinancingBenefit = () => {
    const currentOverpayment = calculateOverpayment();
    const newRate = Math.max(5.9, interestRate - 3); // Минимальная ставка при рефинансировании
    const monthlyRate = newRate / 100 / 12;
    
    let newPayment: number;
    if (paymentType === 'annuity') {
      const annuityCoefficient = (monthlyRate * Math.pow(1 + monthlyRate, loanTerm)) / 
                                (Math.pow(1 + monthlyRate, loanTerm) - 1);
      newPayment = Math.round(loanAmount * annuityCoefficient);
    } else {
      const principalPayment = loanAmount / loanTerm;
      const interestPayment = loanAmount * monthlyRate;
      newPayment = Math.round(principalPayment + interestPayment);
    }
    
    const newOverpayment = (newPayment * loanTerm) - loanAmount;
    const savings = currentOverpayment - newOverpayment;
    
    return {
      newRate,
      newPayment,
      savings: Math.max(0, savings),
      percentage: Math.round((savings / currentOverpayment) * 100)
    };
  };

  useEffect(() => {
    calculatePaymentSchedule();
  }, [loanAmount, loanTerm, interestRate, paymentType]);

  const monthlyPayment = calculatePayment();
  const totalPayment = calculateTotalPayment();
  const overpayment = calculateOverpayment();
  const refinancing = calculateRefinancingBenefit();

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="md"
      fullWidth
      fullScreen={isMobile}
      PaperProps={{
        sx: {
          borderRadius: isMobile ? 0 : 2,
          bgcolor: isDarkMode ? '#1a1a1a' : '#ffffff',
          backgroundImage: 'none',
          maxHeight: isMobile ? '100vh' : '90vh',
        }
      }}
    >
      <DialogTitle sx={{ 
        bgcolor: isDarkMode ? 'rgba(45, 45, 45, 0.8)' : 'rgba(248, 253, 249, 0.9)',
        borderBottom: `1px solid ${isDarkMode ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)'}`,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        backdropFilter: 'blur(10px)',
      }}>
        <Box display="flex" alignItems="center" gap={2}>
          <Calculate color="primary" />
          <Typography variant="h6" fontWeight={600}>
            Кредитный калькулятор
          </Typography>
          <Chip 
            label="AI-powered" 
            size="small" 
            color="primary" 
            variant="outlined"
            icon={<TrendingUp fontSize="small" />}
          />
        </Box>
        <IconButton onClick={onClose} size="small">
          <Close />
        </IconButton>
      </DialogTitle>

      <DialogContent sx={{ p: 0 }}>
        <Tabs
          value={activeTab}
          onChange={(e, newValue) => setActiveTab(newValue)}
          variant={isMobile ? "fullWidth" : "standard"}
          sx={{ 
            borderBottom: 1, 
            borderColor: 'divider',
            bgcolor: isDarkMode ? 'rgba(45, 45, 45, 0.5)' : 'rgba(248, 253, 249, 0.5)',
          }}
        >
          <Tab 
            label="Калькулятор" 
            icon={<Calculate fontSize="small" />} 
            iconPosition="start"
          />
          <Tab 
            label="График платежей" 
            icon={<Timeline fontSize="small" />} 
            iconPosition="start"
            disabled={!showSchedule}
          />
          <Tab 
            label="Рефинансирование" 
            icon={<TrendingUp fontSize="small" />} 
            iconPosition="start"
          />
        </Tabs>

        <Box p={isMobile ? 2 : 3}>
          {activeTab === 0 && (
            <Grid container spacing={3}>
              {/* Левая колонка - настройки */}
              <Grid item xs={12} md={6}>
                <Paper 
                  elevation={0}
                  sx={{ 
                    p: 2, 
                    borderRadius: 2,
                    bgcolor: isDarkMode ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.02)',
                    border: `1px solid ${isDarkMode ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)'}`,
                  }}
                >
                  <Typography variant="subtitle1" fontWeight={600} gutterBottom>
                    Параметры кредита
                  </Typography>
                  
                  {/* Сумма кредита */}
                  <Box mb={3}>
                    <Box display="flex" justifyContent="space-between" mb={1}>
                      <Typography variant="body2" color="text.secondary">
                        Сумма кредита
                      </Typography>
                      <Typography variant="body2" fontWeight={600} color="primary">
                        {loanAmount.toLocaleString('ru-RU')} ₽
                      </Typography>
                    </Box>
                    <Slider
                      value={loanAmount}
                      onChange={(e, value) => setLoanAmount(value as number)}
                      min={10000}
                      max={5000000}
                      step={10000}
                      marks={[
                        { value: 10000, label: '10 тыс' },
                        { value: 5000000, label: '5 млн' }
                      ]}
                    />
                    <Box display="flex" justifyContent="space-between" mt={1}>
                      <Button 
                        size="small" 
                        onClick={() => setLoanAmount(100000)}
                        variant="outlined"
                      >
                        100 тыс
                      </Button>
                      <Button 
                        size="small" 
                        onClick={() => setLoanAmount(500000)}
                        variant="outlined"
                      >
                        500 тыс
                      </Button>
                      <Button 
                        size="small" 
                        onClick={() => setLoanAmount(1000000)}
                        variant="outlined"
                      >
                        1 млн
                      </Button>
                    </Box>
                  </Box>
                  
                  {/* Срок кредита */}
                  <Box mb={3}>
                    <Box display="flex" justifyContent="space-between" mb={1}>
                      <Typography variant="body2" color="text.secondary">
                        Срок кредита
                      </Typography>
                      <Typography variant="body2" fontWeight={600} color="primary">
                        {loanTerm} месяцев
                      </Typography>
                    </Box>
                    <Slider
                      value={loanTerm}
                      onChange={(e, value) => setLoanTerm(value as number)}
                      min={3}
                      max={60}
                      marks={[
                        { value: 3, label: '3 мес' },
                        { value: 12, label: '1 год' },
                        { value: 36, label: '3 года' },
                        { value: 60, label: '5 лет' }
                      ]}
                    />
                  </Box>
                  
                  {/* Процентная ставка */}
                  <Box mb={3}>
                    <Box display="flex" justifyContent="space-between" mb={1}>
                      <Typography variant="body2" color="text.secondary">
                        Процентная ставка
                      </Typography>
                      <Typography variant="body2" fontWeight={600} color="primary">
                        {interestRate}%
                      </Typography>
                    </Box>
                    <Slider
                      value={interestRate}
                      onChange={(e, value) => setInterestRate(value as number)}
                      min={5.9}
                      max={25}
                      step={0.1}
                      marks={[
                        { value: 5.9, label: '5.9%' },
                        { value: 12.9, label: '12.9%' },
                        { value: 25, label: '25%' }
                      ]}
                    />
                    <Typography variant="caption" color="text.secondary">
                      *Минимальная ставка при рефинансировании: 5.9%
                    </Typography>
                  </Box>
                  
                  {/* Тип платежа */}
                  <Box>
                    <Typography variant="body2" color="text.secondary" gutterBottom>
                      Тип платежа
                    </Typography>
                    <Box display="flex" gap={2}>
                      <Button
                        fullWidth
                        variant={paymentType === 'annuity' ? 'contained' : 'outlined'}
                        onClick={() => setPaymentType('annuity')}
                        startIcon={<AttachMoney />}
                      >
                        Аннуитетный
                      </Button>
                      <Button
                        fullWidth
                        variant={paymentType === 'differentiated' ? 'contained' : 'outlined'}
                        onClick={() => setPaymentType('differentiated')}
                        startIcon={<ShowChart />}
                      >
                        Дифференцированный
                      </Button>
                    </Box>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={showSchedule}
                          onChange={(e) => setShowSchedule(e.target.checked)}
                          color="primary"
                        />
                      }
                      label="Показать график платежей"
                      sx={{ mt: 2 }}
                    />
                  </Box>
                </Paper>
              </Grid>
              
              {/* Правая колонка - результаты */}
              <Grid item xs={12} md={6}>
                <Paper 
                  elevation={0}
                  sx={{ 
                    p: 2, 
                    borderRadius: 2,
                    bgcolor: isDarkMode ? 'rgba(46, 125, 50, 0.1)' : 'rgba(46, 112, 50, 0.05)',
                    border: `1px solid ${isDarkMode ? 'rgba(76, 175, 80, 0.2)' : 'rgba(46, 125, 50, 0.2)'}`,
                    height: '100%',
                  }}
                >
                  <Typography variant="subtitle1" fontWeight={600} gutterBottom color="primary">
                    Результаты расчета
                  </Typography>
                  
                  <Box mb={3}>
                    <Box display="flex" alignItems="center" justifyContent="space-between" mb={2}>
                      <Box>
                        <Typography variant="body2" color="text.secondary">
                          Ежемесячный платеж
                        </Typography>
                        <Typography variant="h4" fontWeight={700} color="primary">
                          {monthlyPayment.toLocaleString('ru-RU')} ₽
                        </Typography>
                      </Box>
                      <Schedule fontSize="large" color="primary" />
                    </Box>
                    
                    <Divider sx={{ my: 2 }} />
                    
                    <Grid container spacing={2}>
                      <Grid item xs={6}>
                        <Box textAlign="center">
                          <Typography variant="body2" color="text.secondary">
                            Общая сумма
                          </Typography>
                          <Typography variant="h6" fontWeight={600}>
                            {totalPayment.toLocaleString('ru-RU')} ₽
                          </Typography>
                        </Box>
                      </Grid>
                      <Grid item xs={6}>
                        <Box textAlign="center">
                          <Typography variant="body2" color="text.secondary">
                            Переплата
                          </Typography>
                          <Typography variant="h6" fontWeight={600} color="error">
                            {overpayment.toLocaleString('ru-RU')} ₽
                          </Typography>
                        </Box>
                      </Grid>
                    </Grid>
                    
                    <Alert 
                      severity="info" 
                      icon={<Info />}
                      sx={{ mt: 2 }}
                    >
                      {paymentType === 'annuity' 
                        ? 'Аннуитетный платеж: одинаковый платеж каждый месяц'
                        : 'Дифференцированный платеж: платеж уменьшается каждый месяц'
                      }
                    </Alert>
                  </Box>
                  
                  <Button
                    fullWidth
                    variant="contained"
                    size="large"
                    startIcon={<TrendingUp />}
                    onClick={() => setActiveTab(2)}
                    sx={{ 
                      bgcolor: isDarkMode ? '#2E7D32' : '#2E7032',
                      '&:hover': { bgcolor: isDarkMode ? '#1b5e20' : '#1b5e20' },
                    }}
                  >
                    Проверить выгоду рефинансирования
                  </Button>
                  
                  <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 2, textAlign: 'center' }}>
                    *Расчеты примерные. Для точного расчета обратитесь в отделение
                  </Typography>
                </Paper>
              </Grid>
            </Grid>
          )}

          {activeTab === 1 && (
            <Box>
              <Typography variant="h6" gutterBottom>
                График платежей
              </Typography>
              <TableContainer 
                component={Paper} 
                variant="outlined"
                sx={{ 
                  maxHeight: 400,
                  bgcolor: isDarkMode ? 'rgba(255,255,255,0.05)' : 'inherit',
                }}
              >
                <Table size="small" stickyHeader>
                  <TableHead>
                    <TableRow>
                      <TableCell>Месяц</TableCell>
                      <TableCell align="right">Платеж</TableCell>
                      <TableCell align="right">Основной долг</TableCell>
                      <TableCell align="right">Проценты</TableCell>
                      <TableCell align="right">Остаток долга</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {schedule.map((row) => (
                      <TableRow key={row.month} hover>
                        <TableCell>{row.month}</TableCell>
                        <TableCell align="right">{row.payment.toLocaleString('ru-RU')} ₽</TableCell>
                        <TableCell align="right">{row.principal.toLocaleString('ru-RU')} ₽</TableCell>
                        <TableCell align="right">{row.interest.toLocaleString('ru-RU')} ₽</TableCell>
                        <TableCell align="right">{row.balance.toLocaleString('ru-RU')} ₽</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            </Box>
          )}

          {activeTab === 2 && (
            <Box>
              <Typography variant="h6" gutterBottom>
                Выгода рефинансирования
              </Typography>
              
              <Paper 
                elevation={0}
                sx={{ 
                  p: 3, 
                  borderRadius: 2,
                  bgcolor: isDarkMode ? 'rgba(255, 193, 7, 0.1)' : 'rgba(255, 193, 7, 0.05)',
                  border: `1px solid ${isDarkMode ? 'rgba(255, 193, 7, 0.3)' : 'rgba(255, 193, 7, 0.2)'}`,
                  mb: 3,
                }}
              >
                <Grid container spacing={3}>
                  <Grid item xs={12} md={6}>
                    <Typography variant="body2" color="text.secondary" gutterBottom>
                      Текущие условия
                    </Typography>
                    <Box mb={2}>
                      <Typography variant="body2">Ставка: <strong>{interestRate}%</strong></Typography>
                      <Typography variant="body2">Платеж: <strong>{monthlyPayment.toLocaleString('ru-RU')} ₽</strong></Typography>
                      <Typography variant="body2">Переплата: <strong>{overpayment.toLocaleString('ru-RU')} ₽</strong></Typography>
                    </Box>
                  </Grid>
                  
                  <Grid item xs={12} md={6}>
                    <Typography variant="body2" color="text.secondary" gutterBottom>
                      После рефинансирования
                    </Typography>
                    <Box mb={2}>
                      <Typography variant="body2">
                        Новая ставка: <strong style={{ color: '#4caf50' }}>{refinancing.newRate}%</strong>
                      </Typography>
                      <Typography variant="body2">
                        Новый платеж: <strong style={{ color: '#4caf50' }}>{refinancing.newPayment.toLocaleString('ru-RU')} ₽</strong>
                      </Typography>
                      <Typography variant="body2">
                        Экономия: <strong style={{ color: '#4caf50' }}>{refinancing.savings.toLocaleString('ru-RU')} ₽</strong>
                      </Typography>
                    </Box>
                  </Grid>
                </Grid>
                
                <Divider sx={{ my: 2 }} />
                
                <Box textAlign="center">
                  <Typography variant="h5" fontWeight={700} color="success.main" gutterBottom>
                    Вы сэкономите {refinancing.percentage}%
                  </Typography>
                  <Typography variant="body1">
                    При рефинансировании в Сбере
                  </Typography>
                </Box>
              </Paper>
              
              <Alert 
                severity="success" 
                icon={<Savings />}
                sx={{ mb: 2 }}
              >
                <Typography variant="subtitle2" gutterBottom>
                  Преимущества рефинансирования в Сбере:
                </Typography>
                <ul style={{ margin: 0, paddingLeft: 20 }}>
                  <li>Снижение ставки до 3%</li>
                  <li>Объединение до 5 кредитов</li>
                  <li>Увеличение срока кредита</li>
                  <li>Бесплатная консультация</li>
                </ul>
              </Alert>
              
              <Button
                fullWidth
                variant="contained"
                size="large"
                startIcon={<Calculate />}
                onClick={() => {
                  alert('Заявка на рефинансирование отправлена! С вами свяжется специалист Сбера.');
                }}
              >
                Подать заявку на рефинансирование
              </Button>
            </Box>
          )}
        </Box>
      </DialogContent>

      <DialogActions sx={{ 
        p: 2,
        borderTop: `1px solid ${isDarkMode ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)'}`,
        bgcolor: isDarkMode ? 'rgba(45, 45, 45, 0.5)' : 'rgba(248, 253, 249, 0.5)',
        backdropFilter: 'blur(10px)',
      }}>
        <Button onClick={onClose} color="inherit">
          Закрыть
        </Button>
        <Button 
          variant="contained" 
          onClick={() => {
            alert('Расчет сохранен! Можете отправить его себе на email.');
          }}
        >
          Сохранить расчет
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default CreditCalculator;