import React, { useContext } from 'react';
import { 
  IconButton, 
  Tooltip, 
  Badge,
  Box 
} from '@mui/material';
import { Calculate, TrendingUp } from '@mui/icons-material';
import { ThemeContext } from '../../App';

interface CalculatorButtonProps {
  onClick: () => void;
  isMobile?: boolean;
}

const CalculatorButton: React.FC<CalculatorButtonProps> = ({ onClick, isMobile = false }) => {
  const { isDarkMode } = useContext(ThemeContext);

  return (
    <Tooltip title="Кредитный калькулятор" arrow placement="top">
      <Box sx={{ position: 'relative' }}>
        <IconButton
          onClick={onClick}
          sx={{
            bgcolor: isDarkMode 
              ? 'rgba(46, 125, 50, 0.2)' 
              : 'rgba(46, 112, 50, 0.1)',
            color: isDarkMode ? '#4caf50' : '#2E7032',
            border: `1px solid ${isDarkMode ? 'rgba(76, 175, 80, 0.3)' : 'rgba(46, 112, 50, 0.2)'}`,
            borderRadius: 2,
            p: isMobile ? 1.2 : 1.5,
            '&:hover': {
              bgcolor: isDarkMode 
                ? 'rgba(76, 175, 80, 0.3)' 
                : 'rgba(46, 125, 50, 0.15)',
              transform: 'translateY(-2px)',
              boxShadow: 2,
            },
            transition: 'all 0.3s ease',
          }}
        >
          <Calculate fontSize={isMobile ? "medium" : "large"} />
          {/* Маленькая иконка процента сверху */}
          <Box
            sx={{
              position: 'absolute',
              top: 4,
              right: 4,
              bgcolor: isDarkMode ? '#ff9800' : '#ff9800',
              borderRadius: '50%',
              width: 16,
              height: 16,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}
          >
            <TrendingUp sx={{ fontSize: 10, color: 'white' }} />
          </Box>
        </IconButton>
        {/* Бейдж "NEW" для привлечения внимания */}
        <Badge
          color="error"
          badgeContent="NEW"
          sx={{
            position: 'absolute',
            top: -8,
            right: -8,
            '& .MuiBadge-badge': {
              fontSize: isMobile ? '0.6rem' : '0.7rem',
              padding: '0 4px',
              borderRadius: 1,
            }
          }}
        />
      </Box>
    </Tooltip>
  );
};

export default CalculatorButton;