import React, { useState, useContext, useEffect } from "react";
import { 
    Box, 
    Paper, 
    Typography, 
    Avatar, 
    IconButton, 
    Tooltip, 
    Snackbar, 
    Alert,
    useMediaQuery,
    useTheme,
    CircularProgress
} from "@mui/material";
import { SmartToy, AccountCircle, Brightness4, Brightness7 } from "@mui/icons-material";
import MessageBubble from "../MessageBubble/MessageBubble";
import InputArea from "../InputArea/InputArea";
import RatingButtons from '../RatingButtons/RatingButtons';
import QuickButtons from "../QuickButtons/QuickButtons";  
import { Message } from "../../features/chat/types";
import { ThemeContext } from '../../App';
import CalculatorButton from '../CalculatorButton/CalculatorButton';
import CreditCalculator from '../CreditCalculator/CreditCalculator';
import GameButton from '../GameButton/GameButton';
import CreditGame from '../CreditGame/CreditGame';

// Импорт API
import { chatApi } from "../../api/chat.api";
import { ApiResponse, ChatMessageRequest, ChatMessageResponse } from "../../api/types";

// Импорт фоновой картинки
import chatPattern from '../../assets/3164116.jpg';
import { marked } from "marked";


const ChatWindow: React.FC = () => {
    const [messages, setMessages] = useState<Message[]>([]);
    const [isLoading, setIsLoading] = useState<boolean>(true);
    const [isSending, setIsSending] = useState<boolean>(false);
    const [sessionId, setSessionId] = useState<string>('');
    
    const [ratings, setRatings] = useState<Record<string, boolean>>({});
    const [notification, setNotification] = useState<{ open: boolean; message: string; severity: 'success' | 'error' }>({
        open: false,
        message: '',
        severity: 'success'
    });
    
    const theme = useTheme();
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
    const isTablet = useMediaQuery(theme.breakpoints.between('sm', 'md'));
    const isDesktop = useMediaQuery(theme.breakpoints.up('md'));
    
    const { toggleTheme, isDarkMode } = useContext(ThemeContext);

    const [calculatorOpen, setCalculatorOpen] = useState(false);
    const [gameOpen, setGameOpen] = useState(false);

    // Инициализация чата при загрузке компонента
    useEffect(() => {
        const initializeChat = async () => {
            setIsLoading(true);
            try {
                // 1. Создаем или получаем сессию
                const sessionResponse = await chatApi.createSession();
                if (sessionResponse.success) {
                    setSessionId(sessionResponse.data.sessionId);
                    
                    // 2. Загружаем историю чата (если есть)
                    const historyResponse = await chatApi.getChatHistory(sessionResponse.data.sessionId);
                    if (historyResponse.success && historyResponse.data.length > 0) {
                        // Конвертируем ответы API в формат компонента
                        const historyMessages: Message[] = historyResponse.data.map(msg => ({
                            id: msg.id,
                            text: msg.text,
                            isUser: msg.isUser,
                            timestamp: new Date(msg.timestamp),
                            senderName: msg.senderName,
                            searchIndicator: msg.searchIndicator,
                        }));
                        setMessages(historyMessages);
                    } else {
                        // 3. Первое приветственное сообщение
                        const welcomeMessage: Message = {
                            id: "1",
                            text: "Здравствуйте! Я AI-помощник Сбербанка по кредитам. Чем могу помочь?",
                            isUser: false,
                            timestamp: new Date(),
                            senderName: "AI-помощник Сбера",
                        };
                        setMessages([welcomeMessage]);
                    }
                    
                    // 4. Получаем быстрые вопросы из API
                    const quickQuestionsResponse = await chatApi.getQuickQuestions();
                    if (quickQuestionsResponse.success) {
                        console.log("Быстрые вопросы загружены:", quickQuestionsResponse.data);
                    }
                }
            } catch (error) {
                console.error("Ошибка инициализации чата:", error);
                // Fallback сообщение
                const errorMessage: Message = {
                    id: "1",
                    text: "Здравствуйте! Я AI-помощник Сбербанка. В настоящее время испытываю некоторые технические трудности.",
                    isUser: false,
                    timestamp: new Date(),
                    senderName: "AI-помощник Сбера",
                };
                setMessages([errorMessage]);
                showNotification("Не удалось подключиться к серверу. Используется локальный режим.", "error");
            } finally {
                setIsLoading(false);
            }
        };
        
        initializeChat();
    }, []);

    // Обновленная функция отправки сообщения с API
    const handleSendMessage = async (text: string, attachments?: File[]) => {
        if (!text.trim() || isSending) return;
        
        setIsSending(true);
        
        // 1. Добавляем сообщение пользователя в UI
        const userMessage: Message = {
            id: Date.now().toString(),
            text,
            isUser: true,
            timestamp: new Date(),
            attachments: attachments?.map(file => ({
                id: `${Date.now()}_${file.name}`,
                name: file.name,
                type: file.type,
                size: file.size,
                url: URL.createObjectURL(file)
            }))
        };
        
        setMessages(prev => [...prev, userMessage]);
        
        try {
            // 2. Отправляем сообщение на сервер
            const request: ChatMessageRequest = {
                message: text,
                sessionId: sessionId,
                attachments: attachments,
                context: {
                    hasCalculator: true,
                    hasGame: true,
                    currentDate: new Date().toISOString(),
                    userDevice: isMobile ? 'mobile' : isTablet ? 'tablet' : 'desktop'
                }
            };
            
            const response = await chatApi.sendMessage(request);
            
            if (response.success) {
                // 3. Добавляем ответ от AI
                const text = await marked.parse(response.data.text);
                const botMessage: Message = {
                    id: response.data.id || `bot_${Date.now()}`,
                    text,
                    isUser: false,
                    timestamp: new Date(response.data.timestamp || new Date()),
                    senderName: response.data.senderName || "AI-помощник Сбера",
                    searchIndicator: response.data.searchIndicator,
                };
                
                setMessages(prev => [...prev, botMessage]);
                
                // 4. Проверяем специальные команды от AI
                const lowerResponse = response.data.text.toLowerCase();
                if (lowerResponse.includes("калькулятор") || lowerResponse.includes("рассчита")) {
                    setTimeout(() => setCalculatorOpen(true), 800);
                } else if (lowerResponse.includes("игра") || lowerResponse.includes("миниигра")) {
                    setTimeout(() => setGameOpen(true), 800);
                }
            } else {
                // Обработка ошибки от сервера
                const errorMessage: Message = {
                    id: `error_${Date.now()}`,
                    text: "Извините, произошла ошибка при обработке вашего запроса. Пожалуйста, попробуйте еще раз.",
                    isUser: false,
                    timestamp: new Date(),
                    senderName: "AI-помощник Сбера",
                };
                setMessages(prev => [...prev, errorMessage]);
            }
        } catch (error) {
            console.error("Ошибка отправки сообщения:", error);
            
            // Fallback ответ
            const fallbackMessage: Message = {
                id: `fallback_${Date.now()}`,
                text: getFallbackResponse(text),
                isUser: false,
                timestamp: new Date(),
                senderName: "AI-помощник Сбера",
                searchIndicator: true,
            };
            
            setMessages(prev => [...prev, fallbackMessage]);
            
            // Проверяем триггеры в локальном режиме
            const lowerQuestion = text.toLowerCase();
            if (lowerQuestion.includes("калькулятор") || lowerQuestion.includes("рассчита")) {
                setTimeout(() => setCalculatorOpen(true), 800);
            } else if (lowerQuestion.includes("игра") || lowerQuestion.includes("миниигра")) {
                setTimeout(() => setGameOpen(true), 800);
            }
            
            showNotification("Соединение нестабильно. Используется локальный режим.", "error");
        } finally {
            setIsSending(false);
        }
    };

    // Локальный fallback для офлайн-режима
    const getFallbackResponse = (userQuestion: string): string => {
        const lowerQuestion = userQuestion.toLowerCase();
        
        if (lowerQuestion.includes("калькулятор") || lowerQuestion.includes("рассчитать")) {
            return "Открываю кредитный калькулятор для вас! Вы можете рассчитать ежемесячный платеж, посмотреть график платежей и проверить выгоду рефинансирования.";
        }
        
        if (lowerQuestion.includes("игра") || lowerQuestion.includes("миниигра")) {
            return "Открываю обучающую мини-игру 'Погаси кредит быстрее'! Узнайте, как досрочное погашение экономит ваши деньги!";
        }
        
        if (lowerQuestion.includes("кредит") && lowerQuestion.includes("получить")) {
            return "Для получения кредита в Сбере вам нужно: 1) Паспорт РФ, 2) Справка о доходах (2-НДФЛ), 3) Заполнить заявку онлайн или в отделении. Ставка от 5.9% годовых.";
        }
        
        if (lowerQuestion.includes("платеж")) {
            return "Для расчета платежа по кредиту укажите: сумму кредита, срок и тип платежей (аннуитетный/дифференцированный). Я могу помочь с расчетом!";
        }
        
        if (lowerQuestion.includes("рефинансирование")) {
            return "Рефинансирование кредитов в Сбере позволяет снизить процентную ставку до 3%. Можно объединить до 5 кредитов из других банков.";
        }
        
        return "Спасибо за вопрос! В настоящее время сервис AI временно недоступен. Для получения персонального предложения обратитесь в ближайшее отделение Сбера.";
    };

    const handleAttachFile = (file: File) => {
        showNotification(`Файл "${file.name}" прикреплен`, 'success');
    };

    const handleRemoveAttachment = (messageId: string, attachmentIndex: number) => {
        setMessages(prev => prev.map(msg => {
            if (msg.id === messageId && msg.attachments) {
                const updatedAttachments = msg.attachments.filter((_, index) => index !== attachmentIndex);
                
                const removedFile = msg.attachments[attachmentIndex];
                if (removedFile) {
                    showNotification(`Файл "${removedFile.name}" удален`, 'success');
                }
                
                return { ...msg, attachments: updatedAttachments };
            }
            return msg;
        }));
    };

    const handleQuickQuestion = async (question: string) => {
        await handleSendMessage(question);
    };

    const handleRateMessage = async (messageId: string, isPositive: boolean) => {
        try {
            const response = await chatApi.rateResponse(messageId, isPositive);
            if (response.success) {
                setRatings(prev => ({ ...prev, [messageId]: isPositive }));
                showNotification('Спасибо за оценку! Ваш отзыв помогает нам улучшать сервис.', 'success');
                
                if (isPositive) {
                    setTimeout(() => {
                        const thanksMessage: Message = {
                            id: (Date.now() + 2).toString(),
                            text: "Спасибо за вашу оценку! Ваш отзыв помогает мне становиться лучше.",
                            isUser: false,
                            timestamp: new Date(),
                            senderName: "AI-помощник Сбера",
                        };
                        setMessages(prev => [...prev, thanksMessage]);
                    }, 500);
                }
            }
        } catch (error) {
            console.error("Ошибка отправки оценки:", error);
            // Локальное сохранение оценки
            setRatings(prev => ({ ...prev, [messageId]: isPositive }));
            showNotification('Оценка сохранена локально', 'success');
        }
    };

    const showNotification = (message: string, severity: 'success' | 'error') => {
        setNotification({ open: true, message, severity });
    };

    const handleCloseNotification = () => {
        setNotification(prev => ({ ...prev, open: false }));
    };

    // Размеры для разных устройств
    const getContainerStyles = () => {
        if (isMobile) {
            return {
                maxWidth: '100%',
                margin: 0,
                mt: 0,
                height: '100vh',
                borderRadius: 0,
            };
        }
        if (isTablet) {
            return {
                maxWidth: '95%',
                margin: 'auto',
                mt: 3,
                height: '95vh',
                borderRadius: 2,
            };
        }
        return {
            maxWidth: 800,
            margin: 'auto',
            mt: 4,
            height: '90vh',
            borderRadius: 2,
        };
    };

    return (
        <>
            <Paper 
                elevation={isMobile ? 0 : 3} 
                sx={{ 
                    ...getContainerStyles(),
                    display: "flex",
                    flexDirection: "column",
                    position: 'relative',
                    overflow: 'hidden',
                    backgroundImage: `url(${chatPattern})`,
                    backgroundSize: 'cover',
                    backgroundPosition: 'center',
                    backgroundRepeat: 'no-repeat',
                    backgroundColor: isDarkMode ? '#1a1a1a' : '#f8fdf9',
                    '&::before': {
                        content: '""',
                        position: 'absolute',
                        top: 0,
                        left: 0,
                        right: 0,
                        bottom: 0,
                        backgroundColor: isDarkMode 
                            ? 'rgba(26, 26, 26, 0.85)'
                            : 'rgba(255, 255, 255, 0.85)',
                        backdropFilter: isDarkMode ? 'blur(8px)' : 'none',
                        WebkitBackdropFilter: isDarkMode ? 'blur(8px)' : 'none',
                        zIndex: 0,
                    }
                }}
            >
                {/* Шапка чата */}
                <Box 
                    sx={{ 
                        p: isMobile ? 1.5 : isTablet ? 2 : 3, 
                        display: "flex", 
                        alignItems: "center", 
                        justifyContent: "space-between", 
                        borderBottom: "1px solid",
                        borderColor: isDarkMode ? "rgba(255,255,255,0.1)" : "divider",
                        flexShrink: 0,
                        bgcolor: isDarkMode 
                            ? 'rgba(45, 45, 45, 0.9)'
                            : 'rgba(255, 255, 255, 0.95)',
                        backdropFilter: isDarkMode ? 'blur(10px)' : 'blur(4px)',
                        WebkitBackdropFilter: isDarkMode ? 'blur(10px)' : 'blur(4px)',
                        position: 'relative',
                        zIndex: 1,
                    }}
                >
                    <Box display="flex" alignItems="center" gap={isMobile ? 1 : 2}>
                        <Avatar sx={{ 
                            bgcolor: "primary.main",
                            width: isMobile ? 36 : 40,
                            height: isMobile ? 36 : 40
                        }}>
                            <SmartToy fontSize={isMobile ? "small" : "medium"} />
                        </Avatar>
                        <Box>
                            <Typography 
                                variant={isMobile ? "subtitle1" : "h6"} 
                                color={isDarkMode ? "white" : "primary"}
                                sx={{ 
                                    fontSize: isMobile ? '0.95rem' : '1.1rem',
                                    fontWeight: isMobile ? 600 : 700
                                }}
                            >
                                {isMobile ? "Кредитный ассистент" : "Кредитный AI-помощник Сбера"}
                            </Typography>
                            <Typography 
                                variant="caption" 
                                color={isDarkMode ? "rgba(255,255,255,0.7)" : "text.secondary"}
                                sx={{ fontSize: isMobile ? '0.7rem' : '0.75rem' }}
                            >
                                {isMobile ? "Онлайн" : `Онлайн • Сессия: ${sessionId ? sessionId.substring(0, 8) + '...' : 'загрузка...'}`}
                            </Typography>
                        </Box>
                    </Box>
                    
                    <Box display="flex" alignItems="center" gap={isMobile ? 0.5 : 1}>
                        {isLoading && (
                            <CircularProgress size={20} color="inherit" sx={{ mr: 1 }} />
                        )}
                        
                        <Tooltip title={isDarkMode ? "Светлая тема" : "Тёмная тема"}>
                            <IconButton 
                                onClick={toggleTheme} 
                                color={isDarkMode ? "inherit" : "default"}
                                size={isMobile ? "small" : "medium"}
                                sx={{ 
                                    p: isMobile ? 0.5 : 1,
                                    bgcolor: isDarkMode ? 'rgba(255, 255, 255, 0.1)' : 'rgba(46, 125, 50, 0.1)',
                                    '&:hover': {
                                        bgcolor: isDarkMode ? 'rgba(255, 255, 255, 0.2)' : 'rgba(46, 125, 50, 0.2)',
                                    }
                                }}
                            >
                                {isDarkMode ? 
                                    <Brightness7 fontSize={isMobile ? "small" : "medium"} /> : 
                                    <Brightness4 fontSize={isMobile ? "small" : "medium"} />
                                }
                            </IconButton>
                        </Tooltip>

                        {/* Кнопка калькулятора */}
                        <Tooltip title="Кредитный калькулятор" arrow>
                            <CalculatorButton 
                                onClick={() => setCalculatorOpen(true)}
                                isMobile={isMobile}
                            />
                        </Tooltip>

                        {/* Кнопка игры */}
                        <Tooltip title="Мини-игра: Погаси кредит быстрее!" arrow>
                            <GameButton 
                                onClick={() => setGameOpen(true)}
                                isMobile={isMobile}
                            />
                        </Tooltip>
                        
                        <Avatar sx={{ 
                            bgcolor: isDarkMode ? "#2E7D32" : "#1B5E20",
                            width: isMobile ? 32 : 40,
                            height: isMobile ? 32 : 40
                        }}>
                            <AccountCircle fontSize={isMobile ? "small" : "medium"} />
                        </Avatar>
                    </Box>
                </Box>

                {/* Контейнер сообщений */}
                <Box 
                    sx={{ 
                        flexGrow: 1,
                        overflowY: "auto", 
                        p: isMobile ? 1 : isTablet ? 1.5 : 2,
                        display: "flex",
                        flexDirection: "column",
                        gap: isMobile ? 1.5 : 2,
                        position: 'relative',
                        zIndex: 1,
                        backgroundColor: isDarkMode 
                            ? 'rgba(0, 0, 0, 0.15)'
                            : 'rgba(255, 255, 255, 0.25)',
                        WebkitOverflowScrolling: 'touch',
                    }}
                >
                    {isLoading ? (
                        <Box display="flex" justifyContent="center" alignItems="center" height="200px">
                            <CircularProgress />
                        </Box>
                    ) : (
                        <>
                            {messages.map(message => (
                                <React.Fragment key={message.id}>
                                    <MessageBubble 
                                        message={message} 
                                        onRemoveAttachment={handleRemoveAttachment}
                                        isMobile={isMobile}
                                    />
                                    
                                    {/* Кнопки оценки для сообщений бота */}
                                    {!message.isUser && !ratings[message.id] && (
                                        <Box sx={{ 
                                            alignSelf: 'flex-start', 
                                            maxWidth: isMobile ? '85%' : '70%',
                                            ml: isMobile ? 1 : 0
                                        }}>
                                            <RatingButtons 
                                                messageId={message.id}
                                                onRate={handleRateMessage}
                                                isMobile={isMobile}
                                            />
                                        </Box>
                                    )}
                                    
                                    {/* Показать оценку, если уже оценили */}
                                    {!message.isUser && ratings[message.id] !== undefined && (
                                        <Box sx={{ 
                                            alignSelf: 'flex-start',
                                            fontSize: isMobile ? '0.75rem' : '0.875rem',
                                            color: isDarkMode ? 'rgba(255,255,255,0.7)' : 'text.secondary',
                                            display: 'flex',
                                            alignItems: 'center',
                                            gap: 0.5,
                                            ml: isMobile ? 1 : 0
                                        }}>
                                            {ratings[message.id] ? 
                                                (isMobile ? '👍 Полезно' : '👍 Вы оценили ответ как полезный') : 
                                                (isMobile ? '👎 Не полезно' : '👎 Вы оценили ответ как неполезный')
                                            }
                                        </Box>
                                    )}
                                </React.Fragment>
                            ))}
                            
                            {/* Индикатор отправки */}
                            {isSending && (
                                <Box sx={{ alignSelf: 'flex-start', ml: isMobile ? 1 : 0 }}>
                                    <Box display="flex" alignItems="center" gap={1}>
                                        <CircularProgress size={16} />
                                        <Typography variant="caption" color="text.secondary">
                                            AI генерирует ответ...
                                        </Typography>
                                    </Box>
                                </Box>
                            )}
                            
                            {/* Горячие кнопки частых вопросов */}
                            {messages.length === 0 || !messages[messages.length - 1].isUser ? (
                                <QuickButtons 
                                    onQuestionClick={handleQuickQuestion} 
                                    isMobile={isMobile}
                                    onCalculatorClick={() => setCalculatorOpen(true)}
                                    onGameClick={() => setGameOpen(true)}
                                />
                            ) : null}
                        </>
                    )}
                </Box>

                {/* Поле ввода */}
                <Box 
                    sx={{ 
                        flexShrink: 0,
                        position: 'relative',
                        zIndex: 1,
                    }}
                >
                    <InputArea 
                        onSendMessage={handleSendMessage} 
                        onAttachFile={handleAttachFile}
                        disabled={isSending || isLoading}
                    />
                </Box>
            </Paper>

            {/* Уведомления */}
            <Snackbar 
                open={notification.open} 
                autoHideDuration={3000} 
                onClose={handleCloseNotification}
                anchorOrigin={{ 
                    vertical: isMobile ? 'top' : 'bottom', 
                    horizontal: 'center' 
                }}
            >
                <Alert 
                    onClose={handleCloseNotification} 
                    severity={notification.severity}
                    variant="filled"
                    sx={{ 
                        width: isMobile ? '90%' : '100%',
                        fontSize: isMobile ? '0.875rem' : '1rem'
                    }}
                >
                    {notification.message}
                </Alert>
            </Snackbar>

            {/* Кредитный калькулятор */}
            <CreditCalculator 
                open={calculatorOpen}
                onClose={() => setCalculatorOpen(false)}
            />

            {/* Мини-игра */}
            <CreditGame 
                open={gameOpen}
                onClose={() => setGameOpen(false)}
            />
        </>
    );
};

export default ChatWindow;